import java.util.*;

class Solution {
    public int maxBerries(int[][] field) {
        int n = field.length;
        final int NEG = Integer.MIN_VALUE / 2;
        int[][] dp = new int[n][n];                   // dp[r1][r2] at the current step
        for (int[] row : dp) Arrays.fill(row, NEG);
        if (field[0][0] == -1) return 0;
        dp[0][0] = field[0][0];
        for (int t = 1; t <= 2 * n - 2; t++) {
            int[][] nd = new int[n][n];
            for (int[] row : nd) Arrays.fill(row, NEG);
            for (int r1 = Math.max(0, t - (n - 1)); r1 <= Math.min(n - 1, t); r1++) {
                int c1 = t - r1;
                if (field[r1][c1] == -1) continue;
                for (int r2 = r1; r2 <= Math.min(n - 1, t); r2++) {   // r2 >= r1 by symmetry
                    int c2 = t - r2;
                    if (field[r2][c2] == -1) continue;
                    int best = dp[r1][r2];                              // both came from the left
                    if (r1 > 0) best = Math.max(best, dp[r1 - 1][r2]);  // A from above
                    if (r2 > 0) best = Math.max(best, dp[r1][r2 - 1]);  // B from above
                    if (r1 > 0 && r2 > 0) best = Math.max(best, dp[r1 - 1][r2 - 1]);
                    if (best <= NEG / 2) continue;                      // unreachable
                    int gain = field[r1][c1] + (r1 == r2 ? 0 : field[r2][c2]);  // same cell: once
                    nd[r1][r2] = best + gain;
                }
            }
            dp = nd;
        }
        return Math.max(0, dp[n - 1][n - 1]);
    }
}

