class Solution:
    def maxBerries(self, field: List[List[int]]) -> int:
        n = len(field); NEG = -10 ** 9
        dp = [[NEG] * n for _ in range(n)]; dp[0][0] = field[0][0]
        for k in range(1, 2 * n - 1):
            nd = [[NEG] * n for _ in range(n)]
            for r1 in range(max(0, k - n + 1), min(n, k + 1)):
                c1 = k - r1
                if field[r1][c1] == -1: continue
                for r2 in range(r1, min(n, k + 1)):
                    c2 = k - r2
                    if field[r2][c2] == -1: continue
                    best = max(dp[r1][r2], dp[r1 - 1][r2] if r1 else NEG, dp[r1][r2 - 1] if r2 else NEG, dp[r1 - 1][r2 - 1] if r1 and r2 else NEG)
                    if best < 0: continue
                    gain = field[r1][c1] + (field[r2][c2] if r1 != r2 else 0)
                    nd[r1][r2] = best + gain
            dp = nd
        return max(0, dp[n - 1][n - 1])

