function maxBerries(field) {
  const n = field.length; const memo = new Map();
  function go(r1, c1, r2) {
    const c2 = r1 + c1 - r2;
    if (r1 >= n || c1 >= n || r2 >= n || c2 >= n || field[r1][c1] === -1 || field[r2][c2] === -1) return -Infinity;
    if (r1 === n - 1 && c1 === n - 1) return field[r1][c1];
    const key = (r1 * n + c1) * n + r2;
    if (memo.has(key)) return memo.get(key);
    let g = field[r1][c1]; if (r1 !== r2) g += field[r2][c2];
    const b = Math.max(go(r1 + 1, c1, r2 + 1), go(r1 + 1, c1, r2), go(r1, c1 + 1, r2 + 1), go(r1, c1 + 1, r2));
    const res = g + b; memo.set(key, res); return res;
  }
  return Math.max(0, go(0, 0, 0));
}
